import * as react from 'react';
import { SVGProps } from 'react';

type IqonVariant = "outline" | "fill" | "duotone" | "thin";
interface IqonProps extends SVGProps<SVGSVGElement> {
    /** Icon style variant */
    variant?: IqonVariant;
    /** Size in pixels — sets both width and height */
    size?: number | string;
    /** Accessible label — sets aria-label when provided */
    label?: string;
}

/**
 * Acbs icon
 * Variants: outline, fill, duotone
 */
declare function Acbs({ variant, size, label, ...props }: IqonProps): react.JSX.Element;
declare namespace Acbs {
    var displayName: string;
    var variants: readonly ["outline", "fill", "duotone"];
}

